import{z as l,x as n,o as r,c as p,q as P,j as A,D as e,d as t,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"交互证明与 IP = PSPACE","description":"","frontmatter":{"title":"交互证明与 IP = PSPACE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interactive-proofs.md","filePath":"cs/interactive-proofs.md","lastUpdated":1791063341000}'),d={name:"cs/interactive-proofs.md"};function B(m,a,C,h,S,f){const s=n("Mermaid");return r(),p("div",null,[a[2]||(a[2]=P('<h1 id="交互证明与-ip-pspace" tabindex="-1">交互证明与 IP = PSPACE <a class="header-anchor" href="#交互证明与-ip-pspace" aria-label="Permalink to &quot;交互证明与 IP = PSPACE&quot;">​</a></h1><div class="epigraph"><p>验证者多项式、可掷硬币，与全能证明者回合交谈；IP 恰好等于 PSPACE。图不同构因此有交互证明。</p><footer>—— 据 Goldwasser, Micali and Rackoff；Shamir, IP = PSPACE, 1992；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/bpp-randomized-class">BPP</a> 的硬币只在一台机器里。缺口是<strong>交互</strong>：证明者 \\(P\\) 无限能，验证者 \\(V\\) 多项式随机，多轮消息。完备：是实例 \\(V\\) 几乎总接受；可靠：否实例任意 \\(P^*\\) 几乎总被拒。\\(\\mathrm{IP}=\\mathrm{PSPACE}\\)（ Shamir）。GNI（图不同构）在 IP 里，却未知是否在 NP——短证书与交互不是一类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NP 是一轮、确定性验证的证书。交互允许：隐藏随机挑战、自适应问题。求和检查、算术化把布尔改成多项式，验证者抽随机点比较。#SAT 的计数证明可放进 IP，从而 PSPACE（TQBF）也可。本课要这层归约直觉，不写 Shamir 的全部多项式。</p><p><span class="marginnote">数字实例：单轮 GNI 里，恶意证明者闭眼猜也有 1/2 答对率；独立重复 20 轮后，靠猜骗过验证者的概率只剩 \\(2^{-20}\\)，约百万分之一——可靠性就是这样按轮数指数级压下去的。</span></p><p>公开随机（Arthur–Merlin）与私硬币在足够轮数下能力接近，点名 AM。一轮公开随机大致在 PH 的第二层附近。</p><h3 id="交互不是「口头-np」" tabindex="-1">交互不是「口头 NP」 <a class="header-anchor" href="#交互不是「口头-np」" aria-label="Permalink to &quot;交互不是「口头 NP」&quot;">​</a></h3><p>证明者不能被相信：可靠对恶意 \\(P^*\\) 成立。零知识是额外性质（模拟），本课不定义 ZK 协议，只声明 IP 的类不等于「有 ZK 证明」。</p><p><span class="marginnote">术语翻译：「完备性」是说真话时验证者会被说服；「可靠性」是说假话时任何狡猾的证明者都几乎骗不过。前者防「证明太弱说不服人」，后者防「证明太容易伪造」。</span></p><p><span class="marginnote">GMR 交互证明。Shamir 1992；Lund–Fortnow–Karloff–Nisan 的 #SAT。Sipser 有简写。本课不引入 MIP = NEXP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用图不同构：验证者随机藏一张图的随机重标，问证明者来自 \\(G\\) 还是 \\(H\\)。不同构则证明者能分；同构则无法优于猜测。说明为何这不是 NP 证书（验证者必须藏随机性）。再点名：算术化把 PSPACE 送进 IP。</p>',13)),(r(),A(o,null,{default:e(()=>[i(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E9%9A%8F%E6%9C%BA%E9%AA%8C%E8%AF%81%E8%80%85%22%5D%20o--o%20P%5B%22%E5%85%A8%E8%83%BD%E8%AF%81%E6%98%8E%E8%80%85%22%5D%0A%20%20V%20--%3E%20IP%5B%22IP%22%5D%0A%20%20IP%20--%3E%20EQ%5B%22%3D%20PSPACE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"\\(\\mathrm{NP}\\subseteq\\mathrm{IP}\\) 显然（证书当消息）。\\(\\mathrm{IP}\\subseteq\\mathrm{PSPACE}\\)：空间枚举消息树、递归算接受概率。另一边 Shamir。于是交互恰好填满上一课的 PSPACE，而不是「NP 的随机版」。",-1)),a[5]||(a[5]=E("p",null,"轮数、私硬币是精细结构；类的等式在多项式轮下成立。",-1)),a[6]||(a[6]=E("p",null,"\\(\\mathrm{IP}\\subseteq PSPACE\\) 的递归：验证者消息树深度多项式、每层多项式分支，空间可复用。另一边 Shamir 把 TQBF 算术化到有限域多项式，证明者逐步打开求和。GNI 展示交互可以藏随机挑战；NP 证书没有「验证者私硬币」这一资源。",-1)),a[7]||(a[7]=E("p",null,"GNI 协议的单轮长这样：关键在重标后的图把「来自哪张」的信息藏进了验证者的私硬币。",-1)),(r(),A(o,null,{default:e(()=>[i(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%AA%8C%E8%AF%81%E8%80%85%E6%8E%B7%E7%A1%AC%E5%B8%81%E9%80%89%20G%20%E6%88%96%20H%22%5D%20--%3E%20R%5B%22%E9%9A%8F%E6%9C%BA%E9%87%8D%E6%A0%87%E9%A1%B6%E7%82%B9%E5%BE%97%20H%E2%80%B2%EF%BC%8C%E9%9A%90%E8%97%8F%E9%80%89%E6%8B%A9%22%5D%0A%20%20R%20--%3E%20Q%5B%22%E6%8A%8A%20H%E2%80%B2%20%E5%8F%91%E7%BB%99%E8%AF%81%E6%98%8E%E8%80%85%EF%BC%9A%E5%AE%83%E6%9D%A5%E8%87%AA%E5%93%AA%E5%BC%A0%E5%8E%9F%E5%9B%BE%3F%22%5D%0A%20%20Q%20--%3E%20A%7B%22%E8%AF%81%E6%98%8E%E8%80%85%E5%9B%9E%E7%AD%94%22%7D%0A%20%20A%20--%3E%20OK%5B%22%E7%AD%94%E5%AF%B9%E4%B8%80%E8%BD%AE%E4%B8%8D%E5%A4%9F%EF%BC%8C%E7%8B%AC%E7%AB%8B%E9%87%8D%E5%A4%8D%20k%20%E8%BD%AE%22%5D%0A%20%20OK%20--%3E%20ACC%5B%22%E5%85%A8%E9%83%A8%E7%AD%94%E5%AF%B9%E6%89%8D%E6%8E%A5%E5%8F%97%22%5D%0A%20%20S%20--%3E%20ISO%7B%22%E8%8B%A5%20G%20%E2%89%85%20H%22%7D%0A%20%20ISO%20--%3E%20L%5B%22%E9%87%8D%E6%A0%87%E5%90%8E%E5%88%86%E5%B8%83%E7%9B%B8%E5%90%8C%EF%BC%8C%E7%8C%9C%E4%B8%AD%E7%8E%87%E8%87%B3%E5%A4%9A%201%2F2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=P('<p><span class="marginnote">常见误区：初学者容易把交互证明想成「递一张短证书、验证者看完签字」；关键差别恰恰是验证者的随机挑战要保密——NP 证书没有「验证者私硬币」这个资源，GNI 才因此有交互证明、却未知有 NP 证书。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写零知识证明实现，不引入密码学假设下的简洁证明。不把 MIP、PCP 混成一轮（PCP 下一课）。后课默认：交互证明的能力是 PSPACE，不是 NP。下一课 PCP 与不可近似。</p><p>IP 填满 PSPACE，不是「随机的 NP」。轮数、私硬币是精细结构；类的等式在多项式轮下成立。零知识是额外模拟性质，本课不把 ZK 协议当 IP 的定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IP：多项式随机验证者 + 交互；等于 PSPACE。</li><li>GNI 展示「有交互证明 ≠ 已知有 NP 证书」。</li><li>可靠必须对恶意证明者成立。</li><li>出处：Goldwasser, Micali and Rackoff；Shamir, 1992。</li></ul>',6))])}const D=l(d,[["render",B]]);export{u as __pageData,D as default};
